INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.126.0',
  '2026-11-04',
  'Пульт ТВ: в режиме «Файлы» видна вся папка, просмотр фото, PDF и текста, свои названия файлов',
  E'В режиме «📁 Файлы» теперь видно всё, что лежит в папке: фотографии, PDF, тексты, архивы — а не только видео и музыка. У каждого файла свой значок.\n\nНад списком появился переключатель «ℹ Больше информации»: под названием показываются размер, разрешение фото, качество звука (например, flac · 48 кГц · 16 бит), число страниц PDF, дата съёмки, а у папки — сколько в ней файлов и сколько они весят. Эти сведения медиатека собирает заранее, сама, поэтому папка открывается так же быстро, как раньше.\n\nФото, PDF и тексты открываются прямо на месте плеера: стрелками листаются снимки и страницы, OK — во весь экран, «Назад» — обратно к списку.\n\nСправа у каждой строки — карандаш ✏. В нём можно задать заголовок — понятное название, которое показывается вместо имени файла (и в визуальном режиме тоже), — или переименовать сам файл. Позиция просмотра и всё остальное при переименовании не теряются.',
  E'Медиаагент: `browseAll` (`/api/browse?all=1`) отдаёт и не-медиа, служебное рядом с фильмом (`Имя.jpg`, `Имя.info.json`) прячется вне библиотек фото. Индекс файлов `fileindex.go` (`fileindex.json`, вне копии разметки): фоновая задача «Обход файлов» через 2 мин после старта и раз в 6 ч, сверка по размеру и mtime; видео — общий кэш ffprobe, звук — свой ffprobe (частота, разрядность), снимки — `image.DecodeConfig` по первым 256 КБ, WebP и EXIF (дата, поворот) — свой разбор, PDF — `pdfinfo`. Защита от отвала диска: корень недоступен — пропуск, ошибка чтения — без вычёркивания, пустой корень при непустом индексе — `errDiskGone`. Переезд мимо агента (однозначная пара размер+mtime) переносит всю память через `moveMemory`. Заголовки `filemeta.json` (ключ — путь, в копии разметки, в `moveMemory`), `POST /api/file/edit {id,name?,title?}` без PIN; заголовок подставляется в `/api/catalog` (`applyTitles`, у фильма в папке — и с файла), browse, item, next-season и `/api/photos`. Просмотр: `/text/{id}` (512 КБ, UTF-8/UTF-16/cp1251), `/api/pdf/{id}` и `/pdf/{id}/{n}` (pdftoppm, кэш `pdf/`). Страница: тумблер `htv.finfo`, ✏ в строке (стрелка вправо — карандаш, ещё раз — панель плеера), просмотрщик `#viewer` вместо `<video>`; в «Задачах» карточка «Обход файлов».'
);
-- +goose StatementEnd

